#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> findDiagonalOrder(std::vector<std::vector<int>>& nums) {
        std::vector<std::vector<int>> diags;
        for (int r = 0; r < (int)nums.size(); ++r) {
            for (int c = 0; c < (int)nums[r].size(); ++c) {
                int d = r + c;
                if (d >= (int)diags.size()) diags.resize(d + 1);
                diags[d].push_back(nums[r][c]);
            }
        }
        std::vector<int> res;
        for (auto& d : diags) {
            res.insert(res.end(), d.rbegin(), d.rend());
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] findDiagonalOrder(List<List<Integer>> nums) {
        List<List<Integer>> diags = new ArrayList<>();
        int count = 0;
        for (int r = 0; r < nums.size(); r++) {
            List<Integer> row = nums.get(r);
            for (int c = 0; c < row.size(); c++) {
                int d = r + c;
                while (diags.size() <= d) diags.add(new ArrayList<>());
                diags.get(d).add(row.get(c));
                count++;
            }
        }
        int[] res = new int[count];
        int idx = 0;
        for (List<Integer> d : diags) {
            for (int i = d.size() - 1; i >= 0; i--) {
                res[idx++] = d.get(i);
            }
        }
        return res;
    }
}

var findDiagonalOrder = function(nums) {
    const diags = [];
    for (let r = 0; r < nums.length; r++) {
        for (let c = 0; c < nums[r].length; c++) {
            const d = r + c;
            if (!diags[d]) diags[d] = [];
            diags[d].push(nums[r][c]);
        }
    }
    const res = [];
    for (let d = 0; d < diags.length; d++) {
        if (diags[d]) {
            for (let i = diags[d].length - 1; i >= 0; i--) {
                res.push(diags[d][i]);
            }
        }
    }
    return res;
};
